def width(tau, dt=0.002, end=40.0, sigma_cm=SIGMA_CM):
    n = round(end / dt)
    assert n % 2 == 0
    ts = [i * dt for i in range(n + 1)]
    weights = [decay(t, tau, sigma_cm) *
               (1 if i in (0, n) else 4 if i % 2 else 2) * dt / 3
               for i, t in enumerate(ts)]

    def spectrum(offset_cm):
        omega = offset_cm * CONVERSION
        return sum(w * math.cos(omega * t) for w, t in zip(weights, ts))

    half = spectrum(0) / 2
    left, right = 0.0, 200.0
    assert spectrum(right) < half
    for _ in range(36):
        middle = (left + right) / 2
        if spectrum(middle) > half:
            left = middle
        else:
            right = middle
    return left + right

